import express, { Request, Response, NextFunction } from 'express';
import zlib from 'zlib';
import crypto from 'crypto';
import { pipeline, Readable } from 'stream';
import { promisify } from 'util';

const app = express();
const pipelineAsync = promisify(pipeline);

interface ServiceToken {
  serviceId: string;
  timestamp: number;
  nonce: string;
}

const TRUSTED_SERVICES = new Map<string, string>([
  ['analytics-svc', 'k8s-secret-analytics-2024'],
  ['ingestion-svc', 'k8s-secret-ingestion-2024'],
  ['reporting-svc', 'k8s-secret-reporting-2024'],
]);

const MAX_COMPRESSED_SIZE = 10 * 1024 * 1024; // 10MB compressed
const DECOMPRESSION_RATIO_LIMIT = 100; // max 100:1 ratio
const MAX_DECOMPRESSED_SIZE = 512 * 1024 * 1024; // 512MB absolute max

function verifyServiceToken(authHeader: string | undefined): ServiceToken | null {
  try {
    if (!authHeader || !authHeader.startsWith('Bearer ')) return null;
    const token = authHeader.slice(7);
    const parts = token.split('.');
    if (parts.length !== 3) return null;

    const [payloadB64, serviceId, signature] = parts;
    const secret = TRUSTED_SERVICES.get(serviceId);
    if (!secret) return null;

    const expectedSig = crypto.createHmac('sha256', secret)
      .update(`${payloadB64}.${serviceId}`)
      .digest('hex');

    const sigBuf = Buffer.from(signature, 'hex');
    const expectedBuf = Buffer.from(expectedSig, 'hex');

    // Guard against timingSafeEqual throwing on unequal-length buffers
    // (also handles invalid/odd hex that produces a short buffer).
    if (sigBuf.length !== expectedBuf.length) return null;

    if (!crypto.timingSafeEqual(sigBuf, expectedBuf)) {
      return null;
    }

    const payload = JSON.parse(Buffer.from(payloadB64, 'base64').toString());
    if (typeof payload.timestamp !== 'number' || !Number.isFinite(payload.timestamp)) {
      return null;
    }
    if (Date.now() - payload.timestamp > 300000) return null; // 5min expiry

    return { serviceId, timestamp: payload.timestamp, nonce: payload.nonce };
  } catch {
    return null;
  }
}

function authMiddleware(req: Request, res: Response, next: NextFunction): void {
  const token = verifyServiceToken(req.headers.authorization);
  if (!token) {
    res.status(401).json({ error: 'Unauthorized' });
    return;
  }
  (req as any).serviceToken = token;
  next();
}

interface DecompressionLimiter {
  compressedSize: number;
  decompressedSize: number;
  checkRatio(): boolean;
}

function createLimiter(compressedSize: number): DecompressionLimiter {
  return {
    compressedSize,
    decompressedSize: 0,
    checkRatio(): boolean {
      if (this.compressedSize === 0) return false;
      const currentRatio = this.decompressedSize / this.compressedSize;
      return currentRatio <= DECOMPRESSION_RATIO_LIMIT;
    }
  };
}

async function decompressPayload(compressedData: Buffer, encoding: string): Promise<Buffer> {
  if (compressedData.length > MAX_COMPRESSED_SIZE) {
    throw new Error(`Compressed payload exceeds ${MAX_COMPRESSED_SIZE} bytes`);
  }

  const limiter = createLimiter(compressedData.length);
  const chunks: Buffer[] = [];

  const decompressor = encoding === 'deflate' ? zlib.createInflate() : zlib.createGunzip();

  return new Promise((resolve, reject) => {
    const source = Readable.from(compressedData);

    decompressor.on('data', (chunk: Buffer) => {
      limiter.decompressedSize += chunk.length;
      chunks.push(chunk);

      if (limiter.decompressedSize > MAX_DECOMPRESSED_SIZE) {
        decompressor.destroy(new Error('Absolute size limit exceeded'));
        return;
      }

      // Check ratio on every chunk
      if (!limiter.checkRatio()) {
        decompressor.destroy(new Error('Decompression ratio exceeded'));
        return;
      }
    });

    decompressor.on('end', () => {
      // Final ratio check
      if (!limiter.checkRatio()) {
        reject(new Error('Final decompression ratio check failed'));
        return;
      }
      resolve(Buffer.concat(chunks));
    });

    decompressor.on('error', (err) => reject(err));
    source.pipe(decompressor);
  });
}

app.post('/api/v1/ingest', authMiddleware, async (req: Request, res: Response) => {
  try {
    const contentEncoding = req.headers['content-encoding'] as string;
    const serviceToken = (req as any).serviceToken as ServiceToken;

    // Trusted services can send larger payloads
    const isTrustedBulk = serviceToken.serviceId === 'ingestion-svc';

    let bodyData: Buffer;
    const rawChunks: Buffer[] = [];

    await new Promise<void>((resolve, reject) => {
      req.on('data', (chunk) => rawChunks.push(chunk));
      req.on('end', () => resolve());
      req.on('error', reject);
    });

    const rawBody = Buffer.concat(rawChunks);

    if (contentEncoding === 'gzip' || contentEncoding === 'deflate') {
      bodyData = await decompressPayload(rawBody, contentEncoding);
    } else {
      bodyData = rawBody;
    }

    const records = JSON.parse(bodyData.toString('utf-8'));
    const recordCount = Array.isArray(records) ? records.length : 1;

    res.status(200).json({
      accepted: true,
      records: recordCount,
      service: serviceToken.serviceId,
    });
  } catch (err: any) {
    if (err.message.includes('ratio') || err.message.includes('size limit')) {
      res.status(413).json({ error: 'Payload too large or suspicious compression ratio' });
    } else {
      res.status(400).json({ error: 'Invalid payload', detail: err.message });
    }
  }
});

app.listen(3000, () => console.log('Ingestion service running on :3000'));

export default app;
